const b = $input.first().json.body || {};
const pick = (...keys) => {
  for (const k of keys) { if (b[k] !== undefined && b[k] !== null && String(b[k]).trim()) return String(b[k]).trim(); }
  return '';
};
return [{ json: {
  name: (pick('name', 'full_name', 'your-name', 'Name') || 'Unknown').slice(0, 200),
  company: pick('company', 'business', 'your-company', 'Company').slice(0, 200),
  email: pick('email', 'your-email', 'Email').slice(0, 320),
  phone: pick('phone', 'tel', 'your-phone', 'Phone').slice(0, 50),
  website: pick('website', 'url', 'Website').slice(0, 500),
  service_interest: pick('service', 'service_interest', 'interest', 'Service').slice(0, 300),
  message: pick('message', 'your-message', 'comments', 'Message').slice(0, 5000),
} }];
